def fizzbuzz(n: int) -> list[str]:
    """
    Devuelve una lista de strings del 1 al n, donde los múltiplos de 3 son 'Fizz',
    los de 5 son 'Buzz' y los de ambos son 'FizzBuzz'. El resto es el número como string.

    Args:
        n: El límite superior (inclusive) del rango.

    Returns:
        Una lista de strings con la secuencia de FizzBuzz.
    """
    result = []
    for i in range(1, n + 1):
        if i % 3 == 0 and i % 5 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(i))
    return result

def buscar(lista, x):
    """
    Busca el índice de un elemento en una lista ordenada usando búsqueda binaria.

    Args:
        lista: Lista ordenada de elementos.
        x: Elemento a buscar.

    Returns:
        El índice del elemento si se encuentra, o -1 si no existe.
    """
    if len(lista) == 0:
        return -1
    if len(lista) == 1:
        return 0 if lista[0] == x else -1

    mid = len(lista) // 2
    if lista[mid] == x:
        return mid
    elif lista[mid] < x:
        return buscar(lista[mid + 1:], x)
    else:
        return buscar(lista[:mid], x)

