def mayor_racha(lista: list) -> tuple | None:
    """
    Encuentra la racha más larga de elementos consecutivos iguales
    y devuelve la tupla (elemento, longitud).
    Si hay empate, devuelve la primera racha encontrada.
    Si la lista está vacía, devuelve None.
    """
    if not lista:
        return None

    max_racha = 1
    max_elemento = lista[0]
    racha_actual = 1

    for i in range(1, len(lista)):
        if lista[i] == lista[i - 1]:
            racha_actual += 1
        else:
            if racha_actual > max_racha:
                max_racha = racha_actual
                max_elemento = lista[i - 1]
            racha_actual = 1

    if racha_actual > max_racha:
        max_racha = racha_actual
        max_elemento = lista[-1]

    return (max_elemento, max_racha)

def a_camel(s: str) -> str:
    """
    Convierte un texto a snake_case a camelCase.

    La primera palabra se mantiene en minúscula y las siguientes
    palabras comienzan con mayúscula, sin guiones bajos.

    Args:
        s: La cadena de texto a convertir.

    Returns:
        La cadena convertida a formato camelCase.
    """
    if not s or not s.strip():
        return s

    words = s.split()
    result = []

    for i, word in enumerate(words):
        if i == 0:
            result.append(word.lower())
        else:
            result.append(word[0].upper() + word[1:].lower())

    return ''.join(result)

def es_anagrama(a: str, b: str) -> bool:
    """
    Verifica si dos textos son anagramas, ignorando mayúsculas y espacios.

    Args:
        a: Primer texto.
        b: Segundo texto.

    Returns:
        True si los textos son anagramas, False en caso contrario.
    """
    a = a.lower().replace(" ", "")
    b = b.lower().replace(" ", "")

    if len(a) != len(b):
        return False

    a_counts = {}
    b_counts = {}

    for char in a:
        a_counts[char] = a_counts.get(char, 0) + 1

    for char in b:
        b_counts[char] = b_counts.get(char, 0) + 1

    return a_counts == b_counts

def balanceado(texto: str) -> bool:
    """
    Verifica si los paréntesis, corchetes y llaves del texto están
    correctamente balanceados y anidados.

    Args:
        texto: La cadena de texto a verificar.

    Returns:
        True si el texto está balanceado, False si no lo es.
    """
    if not texto:
        return True

    open_parens = []
    close_parens = []

    for char in texto:
        if char in '({[':
            open_parens.append(char)
        elif char in ')}]':
            if not open_parens:
                return False
            open_parens.pop()
        else:
            close_parens.append(char)

    return len(open_parens) == 0 and len(close_parens) == 0

def balanceado(s: str) -> bool:
    """
    Verifica si los paréntesis, corchetes y llaves del string están bien
    balanceados y anidados. Los demás caracteres se ignoran.

    Args:
        s: La cadena de texto a verificar.

    Returns:
        True si los paréntesis, corchetes y llaves están balanceados,
        False si no lo son.
    """
    open_count = 0
    for char in s:
        if char == '(':
            open_count += 1
        elif char == '[':
            open_count += 1
        elif char == '{':
            open_count += 1
        elif char == ')':
            open_count -= 1
        elif char == ']':
            open_count -= 1
        elif char == '}':
            open_count -= 1
        # Si el contador es negativo, hay un cierre sin apertura correspondiente
        if open_count < 0:
            return False
    return open_count == 0

def anidar(plano: dict) -> dict:
    """
    Recursivamente anida un diccionario de claves con puntos en un diccionario anidado.

    Ejemplo:
        {'a.b': 1} -> {'a': {'b': 1}}
        {'a.b.c': 1} -> {'a': {'b': {'c': 1}}}
    """
    if not plano:
        return {}

    if '.' not in plano:
        return plano

    # Dividir la clave en partes por puntos
    partes = plano.split('.')

    # Recursivamente anidar las partes
    return {
        partes[0]: anidar(plano[1:])
    }

def comprimir(s: str) -> str:
    """Aplica run-length encoding a una string.

    Cada carácter se repite tantas veces como aparece.
    Si un carácter aparece una sola vez, se representa como 'c1'.

    Args:
        s: La string a comprimir.

    Returns:
        El string comprimirado.
    """
    if not s:
        return ""

    # Contar frecuencias de cada carácter
    counts = {}
    for char in s:
        counts[char] = counts.get(char, 0) + 1

    # Construir el resultado
    result = ""
    for char, freq in counts.items():
        if freq == 1:
            result += char + "1"
        else:
            result += char + str(freq)

    return result

def formatear_bytes(n: int) -> str:
    """
    Convierte un número de bytes a texto legible usando multiplicadores de 1024
    (B, KB, MB, GB) con decimales, salvo para B que va sin decimales.

    Args:
        n: Número de bytes a convertir.

    Returns:
        String representando el tamaño en formato legible.
    """
    if n < 0:
        return "Error: valor negativo"

    if n == 0:
        return "0 B"

    if n < 1024:
        return f"{n} B"

    if n < 1024 * 1024:
        return f"{n // 1024:.1f} KB"

    if n < 1024 * 1024 * 1024:
        return f"{n // 1024**2:.1f} MB"

    return f"{n // 1024**3:.1f} GB"

def parsear_query(s: str) -> dict:
    """
    Convierte un string de query tipo 'a=1&b=2' en un dict {'a':'1','b':'2'}.
    Claves sin valor ('c=') quedan con string vacío.
    String vacío devuelve dict vacío.
    """
    if not s:
        return {}

    result = {}
    current_key = None
    current_value = None

    for part in s.split('&'):
        if '=' in part:
            key, value = part.split('=', 1)
            if value == '':
                result[key] = ''
            else:
                result[key] = value
        else:
            current_key = part
            current_value = None

    return result

def aplana_hasta(lista: list, profundidad: int) -> list:
    """
    Aplana una lista anidada recursivamente hasta la profundidad indicada.

    Args:
        lista: Lista que puede contener listas, diccionarios, tuples, sets, frozensets, etc.
        profundidad: Nivel máximo de anidamiento a aplana (1 = aplana un nivel).

    Returns:
        Lista plana con todos los elementos descompactados.
    """
    if profundidad == 0:
        return lista

    result = []
    for elemento in lista:
        if isinstance(elemento, list):
            result.extend(aplanar_hasta(elemento, profundidad - 1))
        elif isinstance(elemento, dict):
            result.extend(aplanar_hasta(elemento, profundidad - 1))
        elif isinstance(elemento, tuple):
            result.extend(aplanar_hasta(elemento, profundidad - 1))
        elif isinstance(elemento, set):
            result.extend(aplanar_hasta(elemento, profundidad - 1))
        elif isinstance(elemento, frozenset):
            result.extend(aplanar_hasta(elemento, profundidad - 1))
        else:
            result.append(elemento)

    return result

