def suma_romanos(a: str, b: str) -> str:
    """
    Suma dos números romanos y devuelve el resultado en romano.

    Args:
        a: String romano (hasta 3999)
        b: String romano (hasta 3999)

    Returns:
        String romano con el resultado de la suma
    """
    def int_to_roman(num: int) -> str:
        if num == 0:
            return ""
        if num > 0:
            return int_to_roman(num // 1000) + _to_roman(num % 1000)
        else:
            return _to_roman(num // 1000) + "-" + int_to_roman(num % 1000)

    def _to_roman(num: int) -> str:
        if num == 0:
            return ""
        if num > 0:
            return _to_roman(num // 100) + _to_roman(num % 100)
        else:
            return _to_roman(num // 1000) + "-" + _to_roman(num % 1000)

    def roman_to_int(s: str) -> int:
        if not s:
            return 0
        if s[-1] in ('I', 'V', 'X'):
            return int(s[-1]) + roman_to_int(s[:-1])
        if s[-1] in ('L', 'C', 'D', 'M'):
            return int(s[-1]) + roman_to_int(s[:-1])
        if s[-2] in ('IV', 'IX', 'XL', 'XC', 'CD', 'CM'):
            return int(s[-2]) + roman_to_int(s[:-2])
        return int(s[-1]) + roman_to_int(s[:-1])

    a = roman_to_int(a)
    b = roman_to_int(b)
    return int_to_roman(a + b)


