def con_reintentos(fn, veces, max_reintentos):
    """
    Ejecuta fn() y, si lanza una excepción, la reintenta hasta max_reintentos intentos.
    Si todos los intentos fallan, vuelve a lanzar la última excepcion.

    Args:
        fn: Función a ejecutar.
        veces: Número de intentos a intentar.
        max_reintentos: Número máximo de intentos permitidos.

    Returns:
        El resultado de la función si alguna ejecución exitosa.
        Si todos fallan, lanza la última excepción.
    """
    for i in range(veces):
        try:
            return fn()
        except Exception as e:
            if i < max_reintentos - 1:
                continue
            raise e
